package com.naviglass.android;
import android.content.Context;import android.media.MediaMetadataRetriever;import android.net.Uri;import org.json.JSONObject;
/** Read richer metadata only when More Info opens; no music or tags are changed. */
final class TrackDetails {
 static JSONObject read(Context context,String id)throws Exception{Track t=Library.get(context).track(id);if(t==null)throw new IllegalArgumentException("Song unavailable");JSONObject out=t.json(NetworkSources.favourite(context,t));
 if(t.source.startsWith("navidrome:")){if(NetworkSources.item(context,t)==null)throw new IllegalArgumentException("Reconnect this song's Navidrome account");JSONObject song=NetworkSources.api(NetworkSources.account(context),"getSong",new JSONObject().put("id",Uri.parse(t.uri).getLastPathSegment())).getJSONObject("song");for(String field:new String[]{"composer","genre","suffix","bitRate","samplingRate","bitDepth","channels","size","path","albumArtist","created"})if(song.has(field))out.put(field.equals("path")?"file":field,song.get(field));}
 else {out.put("file",t.uri).put("modified",t.modified<100000000000L?t.modified*1000:t.modified);try(MediaMetadataRetriever r=new MediaMetadataRetriever()){r.setDataSource(context,Uri.parse(t.uri));copy(r,out,"composer",MediaMetadataRetriever.METADATA_KEY_COMPOSER);copy(r,out,"albumArtist",MediaMetadataRetriever.METADATA_KEY_ALBUMARTIST);copy(r,out,"genre",MediaMetadataRetriever.METADATA_KEY_GENRE);copy(r,out,"date",MediaMetadataRetriever.METADATA_KEY_DATE);String bitrate=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_BITRATE);if(bitrate!=null)out.put("bitRate",Long.parseLong(bitrate)/1000);if(android.os.Build.VERSION.SDK_INT>=31){copy(r,out,"samplingRate",MediaMetadataRetriever.METADATA_KEY_SAMPLERATE);copy(r,out,"bitDepth",MediaMetadataRetriever.METADATA_KEY_BITS_PER_SAMPLE);}}catch(Exception ignored){}}
 return out;}
 private static void copy(MediaMetadataRetriever r,JSONObject out,String key,int field)throws Exception{String value=r.extractMetadata(field);if(value!=null&&!value.isEmpty())out.put(key,value);}
}
